UPDATE users SET enabled=0,username=#{anonymized_username},email='',password_hash=#{password_hash},api_key=#{revoked_key},
                 session_version=session_version+1,deleted_at=#{deleted_at}
WHERE id=#{user_id} AND deleted_at IS NULL

UPDATE subscription_plans
name = #{changes.name}, description = #{changes.description}, price = #{changes.price}, duration_days = #{changes.duration_days}, daily_amount = #{changes.daily_amount}, daily_tokens = #{changes.daily_tokens}, enabled = #{changes.enabled}, updated_at = #{changes.updated_at}
WHERE id = #{plan_id}

UPDATE user_subscriptions
SET ends_at = #{ends_at}
WHERE id = #{subscription_id} AND user_id = #{user_id} AND plan_id = #{plan_id} AND status = 'ACTIVE'

UPDATE user_subscriptions
starts_at = #{changes.starts_at}, ends_at = #{changes.ends_at}, status = #{changes.status}, auto_renew = #{changes.auto_renew},
WHERE id = #{subscription_id} AND user_id = #{user_id}

UPDATE user_quota_policies
name = #{changes.name}, daily_amount = #{changes.daily_amount}, daily_tokens = #{changes.daily_tokens}, hourly_tokens = #{changes.hourly_tokens}, hourly_window_hours = #{changes.hourly_window_hours}, starts_at = #{changes.starts_at}, ends_at = #{changes.ends_at}, enabled = #{changes.enabled}, updated_at = #{changes.updated_at}
WHERE id = #{quota_id} AND user_id = #{user_id}

mapper.select:
SELECT COALESCE(SUM(x.cost),0) free_cost,COALESCE(SUM(x.tokens),0) free_tokens FROM (
  SELECT a.cost cost,a.tokens tokens FROM usage_allocations a
  WHERE a.user_id=#{user_id} AND a.kind='FREE' AND a.entitlement_id=#{quota_id}
    AND a.created_at >= #{start_at} AND (#{end_at} IS NULL OR a.created_at < #{end_at})
  UNION ALL
  SELECT u.free_cost cost,u.free_tokens tokens FROM usage_records u
  WHERE u.user_id=#{user_id} AND u.quota_id=#{quota_id} AND u.created_at >= #{start_at}
    AND (#{end_at} IS NULL OR u.created_at < #{end_at})
    AND NOT EXISTS(SELECT 1 FROM usage_allocations a WHERE a.usage_id=u.id AND a.kind='FREE')
) x

SELECT COALESCE(SUM(x.cost),0) subscription_cost,COALESCE(SUM(x.tokens),0) subscription_tokens FROM (
  SELECT a.cost cost,a.tokens tokens FROM usage_allocations a
  WHERE a.kind='SUBSCRIPTION' AND a.entitlement_id=#{subscription_id}
    AND a.created_at >= #{start_at} AND (#{end_at} IS NULL OR a.created_at < #{end_at})
  UNION ALL
  SELECT u.subscription_cost cost,u.subscription_tokens tokens FROM usage_records u
  WHERE u.subscription_id=#{subscription_id} AND u.created_at >= #{start_at}
    AND (#{end_at} IS NULL OR u.created_at < #{end_at})
    AND NOT EXISTS(SELECT 1 FROM usage_allocations a WHERE a.usage_id=u.id AND a.kind='SUBSCRIPTION')
) x

SELECT CASE WHEN EXISTS(
    SELECT 1 FROM user_quota_policies WHERE user_id = #{user_id} AND enabled = 1 AND starts_at <= #{now} AND (ends_at IS NULL OR ends_at > #{now})
) OR EXISTS(
    SELECT 1 FROM user_subscriptions s JOIN subscription_plans p ON p.id = s.plan_id
    WHERE s.user_id = #{user_id} AND s.status = 'ACTIVE' AND p.enabled = 1 AND s.starts_at <= #{now} AND s.ends_at > #{now}
) THEN 1 ELSE 0 END

